contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _recipient) public payable {
        uint256 beforeBal = address(c).balance;
        bool reverted;
        c.withdrawAll(_recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted || !reverted);
    }

    receive() external payable { revert(); }
}

